<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/arqwar-identity.php';
login_required_html();
ensure_room_schema();
if (isset($_GET['leave'])) { unset($_SESSION['room_context'], $_SESSION['room_access']); }
$error='';

// Mantener intacta la validacion de acceso a salas privadas.
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='enter_room') {
    try {
        verify_csrf();
        $id=(int)($_POST['room_id']??0);
        $room=row('SELECT * FROM game_rooms WHERE id=? AND is_active=1',[$id]);
        if (!$room) throw new RuntimeException('Sala no encontrada.');
        $game=get_game((int)$room['game_id']);
        if (!$game || $game['status']==='finished') throw new RuntimeException('Esta sala ya finalizó.');
        $u=current_user();
        $gm=is_admin() || (int)$room['created_by']===(int)$u['id'];
        if (!$gm && !room_can_enter((int)$room['game_id'])) throw new RuntimeException('No perteneces a un equipo de esta partida.');
        if (!$gm && (int)$room['is_private']===1 && !password_verify((string)($_POST['password']??''),(string)$room['password_hash'])) throw new RuntimeException('Contraseña de sala incorrecta.');
        room_grant_access($id,$gm?'gm':'player');
        $_SESSION['room_context']=['room_id'=>$id,'game_id'=>(int)$room['game_id'],'role'=>$gm?'gm':'player'];
        header('Location: room.php?game_id='.(int)$room['game_id']); exit;
    } catch(Throwable $e) { $error=$e->getMessage(); }
}

$q=trim((string)($_GET['q']??''));
$like='%'.$q.'%';
$rooms=rows("SELECT r.*,g.name game_name,g.status game_status,g.current_round,g.max_rounds,s.area,s.name scenario_name,u.display_name gm_name
    FROM game_rooms r JOIN games g ON g.id=r.game_id JOIN scenarios s ON s.id=g.scenario_id
    LEFT JOIN app_users u ON u.id=r.created_by
    WHERE r.is_active=1 AND g.status<>'finished' AND (?='' OR r.name LIKE ? OR g.name LIKE ?)
    ORDER BY g.id DESC",[$q,$like,$like]);
$csrf=csrf_token();
$u=current_user();

// Indicadores verdaderos, calculados de la informacion existente.
$roomCards=[];
$totalConnected=0;
$totalRunning=0;
$areas=[];
foreach($rooms as $i=>$r){
    $individual=game_is_individual((int)$r['game_id']);
    $canManage=is_admin() || (int)$r['created_by']===(int)$u['id'];
    $canPlay=$canManage || $individual || (bool)user_game_team((int)$r['game_id']);
    $players=room_active_player_count((int)$r['id']);
    $competitors=(int)(row('SELECT COUNT(*) n FROM teams WHERE game_id=?',[(int)$r['game_id']])['n']??0);
    $status=strtolower((string)$r['game_status']);
    $totalConnected+=$players;
    if($status==='running') $totalRunning++;
    if(!empty($r['area'])) $areas[(string)$r['area']]=true;
    $roomCards[]=['room'=>$r,'individual'=>$individual,'canManage'=>$canManage,'canPlay'=>$canPlay,
      'players'=>$players,'competitors'=>$competitors,'status'=>$status,'photo'=>($i%5)+1];
}
ksort($areas,SORT_NATURAL | SORT_FLAG_CASE);
$finishedGames=(int)(row("SELECT COUNT(*) n FROM games WHERE status='finished'")['n']??0);
?>
