<script src="assets/js/bootstrap.bundle.min.js"></script>
<script>
(function(){
  'use strict';
  const modalEl=document.getElementById('privateModal');
  document.querySelectorAll('.enter-private').forEach(function(button){
    button.addEventListener('click',function(){
      document.getElementById('privateRoom').value=button.dataset.room;
      document.getElementById('privateTitle').textContent=button.dataset.name;
      const modal=bootstrap.Modal.getOrCreateInstance(modalEl,{backdrop:true,keyboard:true,focus:true});
      modal.show();
    });
  });
  if(modalEl){
    modalEl.addEventListener('shown.bs.modal',function(){const input=document.getElementById('roomPassword');if(input)input.focus();});
    modalEl.addEventListener('hidden.bs.modal',function(){window.scrollTo({top:window.scrollY,left:0,behavior:'auto'});});
  }
  const list=document.getElementById('roomsList');
  const cards=Array.from(list.querySelectorAll('.room-card'));
  const mode=document.getElementById('roomFilterMode');
  const area=document.getElementById('roomFilterArea');
  const status=document.getElementById('roomFilterStatus');
  const sort=document.getElementById('roomSort');
  const count=document.getElementById('roomVisibleCount');
  const empty=document.getElementById('roomNoMatches');
  function filterRooms(){
    let shown=0;
    cards.sort((a,b)=>sort.value==='oldest'?Number(a.dataset.gameId)-Number(b.dataset.gameId):Number(b.dataset.gameId)-Number(a.dataset.gameId));
    cards.forEach(function(card){
      const matches=(mode.value==='all'||card.dataset.mode===mode.value)&&(area.value==='all'||card.dataset.area===area.value)&&(status.value==='all'||card.dataset.status===status.value);
      card.hidden=!matches;
      if(matches)shown++;
      list.appendChild(card);
    });
    count.textContent=shown+(shown===1?' sala':' salas');
    empty.hidden=shown>0;
  }
  [mode,area,status,sort].forEach(function(control){control.addEventListener('change',filterRooms);});
  filterRooms();
})();
</script>
